from collections import Counter, defaultdict
def solveB(di):
    H,W=len(di),len(di[0])
    out=[r[:] for r in di]
    pos=defaultdict(list)
    for r in range(H):
        for c in range(W):
            if di[r][c]!=0: pos[di[r][c]].append((r,c))
    # pair pixels sharing a row and a column
    for col,ps in pos.items():
        ps.sort()
        for i in range(len(ps)):
            for j in range(i+1,len(ps)):
                a,b=ps[i],ps[j]
                if a[0]==b[0] or a[1]==b[1]: continue
                r0,r1=min(a[0],b[0]),max(a[0],b[0])
                c0,c1=min(a[1],b[1]),max(a[1],b[1])
                if r1-r0>=2 and c1-c0>=2:
                    for x in range(r0,r1+1):
                        for y in range(c0,c1+1):
                            if x in(r0,r1) or y in(c0,c1): out[x][y]=col
    return out
