def comps(g, conn=4):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; comp=[]
                while st:
                    x,y=st.pop(); comp.append((x,y))
                    for dx in range(-1,2):
                        for dy in range(-1,2):
                            nx,ny=x+dx,y+dy
                            if 0<=nx<H and 0<=ny<W and not seen[nx][ny] and g[nx][ny]!=0:
                                seen[nx][ny]=True; st.append((nx,ny))
                out.append(comp)
    return out
