def find_rects(I,v):
    H,W=len(I),len(I[0]); res=[]
    for i in range(H):
        for j in range(W):
            if I[i][j]==v:
                # try to extend rectangle
                w=1
                while j+w<W and I[i][j+w]==v: w+=1
                h=1
                while i+h<H and all(I[i+h][j+k]==v for k in range(w)): h+=1
                res.append((i,j,w,h))
    return res
